<script setup>
defineProps({
    /**
     * Server-rendered trusted icon HTML from `schema.icons.*` — a complete
     * `<svg class="fi-icon fi-size-...">` element generated by Filament's
     * `generate_icon_html()` with the exact Heroicon + alias pairs the stock
     * blades use (documented contract). Renders nothing when missing, so a
