     */
    html: {
        type: String,
        default: null,
    },
})
</script>

<template>
    <!-- eslint-disable-next-line vue/no-v-html — server-rendered trusted SVG (documented contract) -->
    <span
        v-if="html"
        class="fi-vue-ta-trusted-icon"
        v-html="html"
    />
</template>
